import{_ as r,o as a,c as t,a2 as l}from"./chunks/framework.CU6jEZEM.js";const p=JSON.parse('{"title":"调整历史保存时间说明","description":"","frontmatter":{"title":"调整历史保存时间说明","date":"2026-10-14T16:03:21.000Z","lastmod":"2026-11-24T18:11:40.000Z"},"headers":[],"relativePath":"guide/1268.md","filePath":"guide/帮助文档/专项说明/调整历史保存时间说明.md"}'),i={name:"guide/1268.md"};function s(o,e,n,_,S,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="调整历史保存时间说明" tabindex="-1">调整历史保存时间说明 <a class="header-anchor" href="#调整历史保存时间说明" aria-label="Permalink to &quot;调整历史保存时间说明&quot;">​</a></h1><p>‍</p><hr><h4 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h4><p>EntisMax和EntisLNG默认使用SqlServerExpress数据库,此数据库有免费的授权,但主要限制是数据库文件不能超过10G,当罐数较多或历史数据保存间隔较短时,保存的数据较大.系统在运行较长时间后,数据库文件可能会超过10G,就无法再写入数据,导致Entis系统无法正常运行.所以,默认情况下,Entis系统会保留1年时间的历史记录,在实际现场实施时,根据罐数和数据保存间隔可以灵活调整.比如,20罐授权,静态1小时间隔,动态5分钟间隔,那么可以设置为保留2年保存期限</p><h4 id="调整历史保存时间方法说明" tabindex="-1">调整历史保存时间方法说明 <a class="header-anchor" href="#调整历史保存时间方法说明" aria-label="Permalink to &quot;调整历史保存时间方法说明&quot;">​</a></h4><p><strong>第一步</strong>：打开系统/数据库清理，如下图：</p><h4 id="更改sqlserver版本" tabindex="-1">更改SqlServer版本 <a class="header-anchor" href="#更改sqlserver版本" aria-label="Permalink to &quot;更改SqlServer版本&quot;">​</a></h4><p>如果即想保存时间够长,又想保存间隔时间紧密,基至于罐数较多,那么唯一的办法,就是更改数据库授权版本,当前的SqlServerExress免费授权版本肯定无法满足要求.</p><ul><li>所有的SqlServer收费版本,对于存储大小都没有限制,性能也较好,可以任意配置存储间隔和时长.</li><li>另一个免费的无限制版本,是SqlServer开发版本,但此版本是没有正式授权的,建议用在不联网的电脑上. <a href="https://alist.tiantai.live/d/kuake/Software/SqlServer/SqlServer2017/SqlServer2017_Developer_CN.zip" target="_blank" rel="noreferrer">中文版SqlServer2017开发版本下载链接</a>​<a href="https://alist.tiantai.live/d/kuake/Software/SqlServer/SqlServer2017/SqlServer2017_Developer_EN.zip" target="_blank" rel="noreferrer">英文版SqlServer2017开发版本下载链接</a></li></ul>',10)])])}const q=r(i,[["render",s]]);export{p as __pageData,q as default};
